#include <stdio.h>
#include <stdlib.h>

int stock[5];
int price[5];

int main(int argc, char **argv) {
    // Initialize stock and price arrays
    for (int i = 0; i < 5; i++) {
        stock[i] = 0;
        price[i] = 0;
    }

    // Handle user input
    for (int i = 1; i < argc; i += 3) {
        char *op = argv[i];
        int sku = atoi(argv[i + 1]);
        int qty = atoi(argv[i + 2]);

        if (strcmp(op, "S") == 0) {
            // Sell operation
            if (stock[sku] >= qty) {
                stock[sku] -= qty;
                printf("SELL sku=%d qty=%d revenue+=%d\n", sku, qty, price[sku] * qty);
            } else {
                printf("INSUFFICIENT_STOCK sku=%d\n", sku);
            }
        } else if (strcmp(op, "R") == 0) {
            // Restock operation
            stock[sku] += qty;
            printf("RESTOCK sku=%d qty=%d\n", sku, qty);
        }
    }

    // Print final stock
    printf("FINAL stock=");
    for (int i = 0; i < 5; i++) {
        printf("%d", stock[i]);
        if (i < 4) printf(",");
    }
    printf("\n");

    return 0;
}
